/*
 * A308289  Lexicographically earliest sequence of distinct nonprimes such
 *          that a(n) + a(n+1) is prime.
 * https://oeis.org/A308289
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 n <= 141, u16 n <= 3654, u32 n <= 3654, u64 n <= 3654,
 *            u128 n <= 3654, big any n
 * Helpers:   is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Formula: sequence generated by lexicographically
 *  (i.e., the smallest possible) augmenting such that
 *  all terms are distinct non‑prime integers and each
 *  consecutive pair sums to a prime.
 *  The rule is applied inductively:
 *
 *      a(1) = 1.
 *      For n > 1, let a(n-1) = p.  a(n) is the smallest
 *      unused non‑prime integer x with
 *              p + x  prime .
 *
 *  The implementation caches all terms computed so far
 *  and expands the cache lazily on demand.
 *  A dynamic bit‑array records used values,
 *  and an on‑the‑fly prime sieve supplies fast look‑ups
 *  for small integers; larger primes are tested by
 *  is_prime_big() (available in the utils library).
 */

#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdint.h>

#include "../utils/is_prime_big.h"

/* Helper: ensure the used bit‑array is large enough. */
static void ensure_used_capacity(size_t needed, unsigned char **used, size_t *cap)
{
    if (needed < *cap) return;
    size_t new_cap = *cap > 0 ? *cap : 64;
    while (new_cap <= needed) new_cap <<= 1;
    unsigned char *new_used = (unsigned char*)calloc(new_cap, 1);
    if (new_used == NULL) exit(EXIT_FAILURE);
    if (*used != NULL) {
        memcpy(new_used, *used, *cap);
        free(*used);
    }
    *used = new_used;
    *cap = new_cap;
}

/* Helper: simple sieve of Eratosthenes up to 'limit' (inclusive). */
static void sieve_primes(size_t limit, unsigned char **flag, size_t *sieve_len)
{
    if (limit <= *sieve_len) return;   /* already large enough */
    unsigned char *new_flag = (unsigned char*)calloc(limit + 1, 1);
    if (new_flag == NULL) exit(EXIT_FAILURE);

    for (size_t i = 2; i <= limit; ++i) new_flag[i] = 1; /* assume prime */

    for (size_t i = 2; i * i <= limit; ++i) {
        if (new_flag[i]) {
            for (size_t j = i * i; j <= limit; j += i) new_flag[j] = 0;
        }
    }

    free(*flag);
    *flag = new_flag;
    *sieve_len = limit;
}

/*
 * Main sequence function
 */
seq_t a(idx_t n)
{
    /* Static state: cache and auxiliary structures */
    static seq_t *cache = NULL;
    static size_t cache_len = 0;   /* number of terms stored */
    static size_t cache_cap = 0;   /* allocated capacity */

    static unsigned char *used = NULL;
    static size_t used_cap = 0;

    static unsigned char *prime_flag = NULL;
    static size_t sieve_limit = 0;

    /* Handle trivial request */
    if (n == 0) return (seq_t)0; /* undefined, but protect */

    /* Ensure cache can hold 'n' terms */
    if (n > cache_cap) {
        size_t new_cap = cache_cap ? cache_cap << 1 : 64;
        while (new_cap < (size_t)n) new_cap <<= 1;
        cache = (seq_t*)realloc(cache, new_cap * sizeof(seq_t));
        if (cache == NULL) exit(EXIT_FAILURE);
        cache_cap = new_cap;
    }

    /* First‑time initialization */
    if (cache_len == 0) {
        /* Cache first term */
        cache[0] = (seq_t)1;
        cache_len = 1;

        /* Mark 1 as used */
        ensure_used_capacity(1, &used, &used_cap);
        used[1] = 1;

        /* Initialise simple sieve upto at least 30 */
        sieve_primes(30, &prime_flag, &sieve_limit);
    }

    /* Generate terms up to n */
    for (; cache_len < (size_t)n; ++cache_len) {
        seq_t prev = cache[cache_len - 1];

        /* Search for the lexicographically smallest suitable value */
        idx_t candidate = 1;
        for (;;) {
            ++candidate;                 /* start from 2 */
            /* expand used array if needed */
            ensure_used_capacity((size_t)candidate, &used, &used_cap);

            if (used[(size_t)candidate]) continue;  /* already used */

            /* Check candidate is non‑prime */
            bool cand_is_prime;
            if ((size_t)candidate <= sieve_limit) {
                cand_is_prime = prime_flag[(size_t)candidate];
            } else {
                cand_is_prime = is_prime_big((seq_t)candidate);
            }
            if (cand_is_prime) continue;   /* skip primes */

            /* Sum with previous term must be prime */
            seq_t sum = prev + (seq_t)candidate;
            if (!is_prime_big(sum)) continue;

            /* Found the term */
            break;
        }

        /* Record the chosen term */
        seq_t chosen = (seq_t)candidate;
        used[(size_t)candidate] = 1;

        /* Ensure sieve covers candidate + prev (sum) if needed */
        /* (sum may exceed sieve_limit; we always use is_prime_big for it) */

        cache[cache_len] = chosen;

        /* Optionally grow the sieve to keep it useful for future checks
           We keep it at least twice the current candidate to avoid
           frequent expansions. */
        size_t needed_sieve = (size_t)candidate * 2 + 100;
        if (needed_sieve > sieve_limit) {
            sieve_primes(needed_sieve, &prime_flag, &sieve_limit);
        }
    }

    return cache[n - 1];
}
